import { z } from 'zod'

const envSchema = z.object({
  // App
  NEXT_PUBLIC_APP_URL: z.string().url(),
  NEXT_PUBLIC_APP_ENV: z.enum(['production', 'staging', 'preview', 'development']).default('development'),
  NODE_ENV: z.enum(['production', 'development', 'test']).default('development'),
  LOG_LEVEL: z.enum(['trace', 'debug', 'info', 'warn', 'error', 'fatal']).default('info'),

  // Supabase
  NEXT_PUBLIC_SUPABASE_URL: z.string().url(),
  NEXT_PUBLIC_SUPABASE_ANON_KEY: z.string().min(1),
  SUPABASE_SERVICE_ROLE_KEY: z.string().min(1).optional(),
  SUPABASE_JWT_SECRET: z.string().min(1).optional(),

  // Dodo Payments
  DODO_API_KEY: z.string().min(1).optional(),
  DODO_PAYMENTS_WEBHOOK_KEY: z
    .string()
    .refine((v) => v.startsWith('whsec_'), {
      message: 'DODO_PAYMENTS_WEBHOOK_KEY must start with whsec_',
    })
    .optional(),

  // Resend
  RESEND_API_KEY: z
    .string()
    .refine((v) => v.startsWith('re_'), {
      message: 'RESEND_API_KEY must start with re_',
    })
    .optional(),
  RESEND_FROM_EMAIL: z.string().email().optional(),

  // Sentry
  NEXT_PUBLIC_SENTRY_DSN: z.string().url().optional(),
  SENTRY_AUTH_TOKEN: z.string().optional(),
  SENTRY_ORG: z.string().optional(),
  SENTRY_PROJECT: z.string().optional(),

  // PostHog
  NEXT_PUBLIC_POSTHOG_KEY: z.string().min(1).optional(),
  NEXT_PUBLIC_POSTHOG_HOST: z.string().url().optional(),

  // Redis (Upstash — rate limiting + cache)
  UPSTASH_REDIS_REST_URL: z.string().url().optional(),
  UPSTASH_REDIS_REST_TOKEN: z.string().min(1).optional(),

  // Redis (private — BullMQ)
  REDIS_PRIVATE_URL: z.string().min(1).optional(),

  // AI (Sprint 9+)
  ANTHROPIC_API_KEY: z.string().min(1).optional(),
})

/**
 * Validated environment variables.
 *
 * During build-time (NEXT_PUBLIC_* only available), Supabase anon key and URL
 * are always required. Server-only keys are optional so the build can run
 * without them — but will fail at runtime if a feature requires them.
 *
 * In production, DODO_PAYMENTS_WEBHOOK_KEY and RESEND_API_KEY are enforced
 * in the handlers that use them, not at boot time, to allow staging deploys
 * with partial secrets.
 */
function createEnv() {
  const result = envSchema.safeParse(process.env)

  if (!result.success) {
    const formatted = result.error.format()
    // Only throw in server runtime, not during static generation of public pages
    if (typeof window === 'undefined' && process.env.NODE_ENV !== 'test') {
      throw new Error(
        `[InkOS] Invalid environment variables:\n${JSON.stringify(formatted, null, 2)}`
      )
    }
    // Return partial in browser/test
    return process.env as unknown as z.infer<typeof envSchema>
  }

  return result.data
}

export const env = createEnv()

import { createBrowserClient } from '@supabase/ssr'
import type { Database } from './types'

/**
 * Browser Supabase client for use in Client Components only.
 *
 * Never import this in Server Components, API routes, or Server Actions.
 * Use lib/supabase/server.ts for those.
 */
export function createClient() {
  return createBrowserClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  )
}

import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import type { Database } from './types'

/**
 * Server Supabase client for Server Components, API Route Handlers, and Server Actions.
 *
 * Uses the anon key + user session cookies.
 * RLS policies apply based on the authenticated user.
 *
 * IMPORTANT: cookies() is async in Next.js 16 — must be awaited.
 */
export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // setAll called from a Server Component — cookies cannot be set
            // middleware handles session refresh
          }
        },
      },
    }
  )
}

/**
 * Service-role Supabase client for webhook handlers and admin operations.
 *
 * Bypasses RLS. NEVER expose to client. Only use server-side.
 */
export function createServiceRoleClient() {
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!serviceRoleKey) {
    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not set')
  }

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    serviceRoleKey,
    {
      cookies: {
        getAll() {
          return []
        },
        setAll() {
          // No-op for service role — no session cookies
        },
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  )
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'
import type { Database } from './types'

/**
 * Updates the session on every request to prevent session expiry.
 *
 * CRITICAL: This function rewrites cookies on BOTH the request (for downstream
 * reads in the same request cycle) AND the response (for the browser to send
 * the updated session token on the next request).
 *
 * This is the Next.js 16 pattern — proxy.ts calls this, not middleware.ts.
 */
export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({ request })

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          // Write on the request so downstream server components can read it
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          // Rebuild the response with the updated request cookies
          supabaseResponse = NextResponse.next({ request })
          // Write on the response so the browser stores the refreshed token
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  // IMPORTANT: Always use getUser() — never getSession() for auth checks.
  // getUser() validates the JWT against the Supabase server.
  const {
    data: { user },
  } = await supabase.auth.getUser()

  // Redirect unauthenticated users away from protected routes
  if (!user) {
    const path = request.nextUrl.pathname
    const isProtected =
      path.startsWith('/dashboard') ||
      path.startsWith('/calendar') ||
      path.startsWith('/appointments') ||
      path.startsWith('/waitlist') ||
      path.startsWith('/clients') ||
      path.startsWith('/consent-forms') ||
      path.startsWith('/ai-design') ||
      path.startsWith('/artists') ||
      path.startsWith('/guest-artists') ||
      path.startsWith('/inventory') ||
      path.startsWith('/commissions') ||
      path.startsWith('/payroll') ||
      path.startsWith('/payments') ||
      path.startsWith('/locations') ||
      path.startsWith('/settings') ||
      path.startsWith('/admin')

    if (isProtected) {
      const redirectUrl = request.nextUrl.clone()
      redirectUrl.pathname = '/login'
      redirectUrl.searchParams.set('redirectedFrom', path)
      return NextResponse.redirect(redirectUrl)
    }
  }

  return supabaseResponse
}

import DodoPayments from '@dodopayments/node'

/**
 * Dodo Payments Node.js SDK client.
 *
 * Server-side only. Never expose DODO_API_KEY to the client.
 *
 * Uses test mode by default in development/staging.
 * Set DODO_API_KEY to a live_ prefixed key in production.
 */
export const dodo = new DodoPayments({
  bearerToken: process.env.DODO_API_KEY,
})

/**
 * Plan tier → Dodo product ID mapping.
 * Product IDs are created in the Dodo dashboard and stored as env vars.
 */
export const PLAN_PRODUCTS = {
  solo: {
    monthly: process.env.DODO_PRODUCT_SOLO_MONTHLY ?? '',
    annual: process.env.DODO_PRODUCT_SOLO_ANNUAL ?? '',
  },
  studio: {
    monthly: process.env.DODO_PRODUCT_STUDIO_MONTHLY ?? '',
