export type BillingCycle = 'monthly' | 'annual'

import { Ratelimit } from '@upstash/ratelimit'
import { Redis } from '@upstash/redis'

/**
 * Upstash Redis rate limiters — three tiers.
 *
 * Requires UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN env vars.
 *
 * Usage:
 *   const ip = headers().get('x-forwarded-for') ?? 'anonymous'
 *   const { success, limit, remaining } = await apiRatelimit.limit(ip)
 *   if (!success) return new Response('Too many requests', { status: 429 })
 */

// Lazy-initialised so tests that don't configure Redis don't crash
let _redis: Redis | null = null

function getRedis(): Redis {
  if (!_redis) {
    _redis = Redis.fromEnv()
  }
  return _redis
}

/** 10 requests per 10 seconds — public unauthenticated endpoints */
export const apiRatelimit = new Ratelimit({
  redis: {
    sadd: (...args) => getRedis().sadd(...args),
    eval: (...args) => getRedis().eval(...args),
  },
  limiter: Ratelimit.slidingWindow(10, '10 s'),
  analytics: true,
  prefix: 'rl:api',
})

/** 60 requests per minute — authenticated user endpoints */
export const authedRatelimit = new Ratelimit({
  redis: {
    sadd: (...args) => getRedis().sadd(...args),
    eval: (...args) => getRedis().eval(...args),
  },
  limiter: Ratelimit.slidingWindow(60, '1 m'),
  analytics: true,
  prefix: 'rl:auth',
})

/** 5 requests per minute — expensive operations (AI, billing, PDF generation) */
export const expensiveRatelimit = new Ratelimit({
  redis: {
    sadd: (...args) => getRedis().sadd(...args),
    eval: (...args) => getRedis().eval(...args),
  },
  limiter: Ratelimit.slidingWindow(5, '1 m'),
  analytics: true,
  prefix: 'rl:exp',
})

import { Redis } from '@upstash/redis'

let _redis: Redis | null = null

function getRedis(): Redis {
  if (!_redis) {
    _redis = Redis.fromEnv()
  }
  return _redis
}

/**
 * Get a cached value by key.
 * Returns null if the key doesn't exist or has expired.
 */
export async function cacheGet<T>(key: string): Promise<T | null> {
  return getRedis().get<T>(key)
}

/**
 * Set a cached value with a TTL in seconds.
 */
export async function cacheSet<T>(key: string, value: T, ttlSec: number): Promise<void> {
  await getRedis().set(key, value, { ex: ttlSec })
}

/**
 * Delete cached keys matching a pattern.
 * Use sparingly — KEYS pattern scan can be slow on large datasets.
 */
export async function cacheBust(pattern: string): Promise<void> {
  const keys = await getRedis().keys(pattern)
  if (keys.length > 0) {
    await getRedis().del(...keys)
  }
}

/**
 * Delete a single cached key.
 */
export async function cacheDel(key: string): Promise<void> {
  await getRedis().del(key)
}

/**
 * Standard cache key builders to prevent key collisions.
 */
export const cacheKeys = {
  studioSubscription: (studioId: string) => `sub:${studioId}`,
  studioMembers: (studioId: string) => `members:${studioId}`,
  userStudios: (userId: string) => `user_studios:${userId}`,
} as const

import { Queue } from 'bullmq'
import IORedis from 'ioredis'

/**
 * BullMQ job queue enqueuer for the web service.
 *
 * The web service ONLY enqueues jobs — it never processes them.
 * Jobs are processed by the worker-jobs Railway service.
 *
 * Uses REDIS_PRIVATE_URL (Railway internal DNS) in production.
 */

let _connection: IORedis | null = null

function getConnection(): IORedis {
  if (!_connection) {
    const redisUrl = process.env.REDIS_PRIVATE_URL
    if (!redisUrl) {
      throw new Error('REDIS_PRIVATE_URL is not configured')
    }
    _connection = new IORedis(redisUrl, {
      // REQUIRED: BullMQ requires maxRetriesPerRequest to be null
      maxRetriesPerRequest: null,
      enableReadyCheck: false,
      lazyConnect: true,
    })
  }
  return _connection
}

export const jobsQueue = new Queue('inkos-jobs', {
  connection: getConnection(),
  defaultJobOptions: {
    attempts: 3,
    backoff: {
      type: 'exponential',
      delay: 2000,
    },
    removeOnComplete: { count: 1000, age: 86400 },
    removeOnFail: { count: 5000 },
  },
})

/**
 * Job payload type map — add new job types here as sprints add features.
 */
export interface JobPayloads {
  'send-email': {
    to: string
    template: string
    data: Record<string, unknown>
  }
  'generate-consent-pdf': {
    submissionId: string
    studioId: string
  }
  'process-ai-design': {
    requestId: string
    studioId: string
  }
  'send-booking-reminder': {
    bookingId: string
    reminderType: 'day_before' | 'hour_before'
  }
  'generate-payroll': {
    studioId: string
    periodStart: string
    periodEnd: string
  }
  'sync-calendar': {
    studioId: string
    artistId: string
  }
  'generate-1099k': {
    studioId: string
    artistId: string
    year: number
  }
}

/**
 * Type-safe job enqueue helper.
 */
export async function enqueueJob<K extends keyof JobPayloads>(
  name: K,
  data: JobPayloads[K],
  options?: { delay?: number; priority?: number }
): Promise<string | undefined> {
  const job = await jobsQueue.add(name, data, options)
  return job.id
}

import pino from 'pino'

/**
 * Structured pino logger.
 *
 * In production (Railway), outputs JSON that Railway aggregates and makes
 * searchable. In development, pino-pretty formats the output for readability.
 *
 * NEVER use console.log in production code — ESLint will block it.
 */
export const logger = pino({
