import type { Json } from './supabase/types'

/**
 * Audit log helper.
 *
 * Writes to the audit_log table via the service-role client (bypasses RLS).
 * Every admin action, billing event, and sensitive data access should be logged here.
 *
 * Failures are logged but never throw — audit failures must not break the main flow.
 */
export async function logAuditAction(
  actorId: string | null,
  action: string,
  target: { type: string; id: string } | null,
  details: Json | null,
  studioId: string | null = null
): Promise<void> {
  try {
    // Lazy import to avoid circular deps and to keep this callable from edge runtimes
    const { createServiceRoleClient } = await import('./supabase/server')
    const supabase = createServiceRoleClient()

    await supabase.from('audit_log').insert({
      actor_id: actorId,
      action,
      target_type: target?.type ?? null,
      target_id: target?.id ?? null,
      studio_id: studioId,
      details,
    })
  } catch (err) {
    // Audit failures must not break the primary operation
    const { logger } = await import('./logger')
    logger.error({ err, action, actorId }, 'audit log write failed')
  }
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * Merge Tailwind CSS class names without conflicts.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Format a currency amount from cents to a display string.
 */
export function formatCurrency(cents: number, currency = 'USD', locale = 'en-US'): string {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(cents / 100)
}

/**
 * Format a date for display.
 */
export function formatDate(date: Date | string, options?: Intl.DateTimeFormatOptions): string {
  const d = typeof date === 'string' ? new Date(date) : date
  return new Intl.DateTimeFormat('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    ...options,
  }).format(d)
}

/**
 * Generate a URL-safe slug from a string.
 */
export function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

/**
 * Truncate a string to a maximum length with an ellipsis.
 */
export function truncate(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str
  return `${str.slice(0, maxLength - 3)}...`
}

/**
 * Type guard to check if a value is a non-null object.
 */
export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

